class Solution:
    def countBlackBlocks(self, m: int, n: int, coordinates: List[List[int]]) -> List[int]:
        from collections import defaultdict
        cnt = defaultdict(int)
        for x, y in coordinates:
            for bx in (x - 1, x):
                for by in (y - 1, y):
                    if 0 <= bx < m - 1 and 0 <= by < n - 1:
                        cnt[(bx, by)] += 1
        arr = [0] * 5
        for c in cnt.values():
            arr[c] += 1
        arr[0] = (m - 1) * (n - 1) - len(cnt)
        return arr

