class Solution {
public:
    vector<long long> countBlackBlocks(int m, int n, vector<vector<int>>& coordinates) {
        map<pair<int,int>, int> cnt;
        for (auto& c : coordinates)
            for (int bx = c[0]-1; bx <= c[0]; bx++)
                for (int by = c[1]-1; by <= c[1]; by++)
                    if (bx >= 0 && bx < m-1 && by >= 0 && by < n-1)
                        cnt[{bx, by}]++;
        vector<long long> arr(5, 0);
        for (auto& [k, v] : cnt) arr[v]++;
        arr[0] = (long long)(m-1) * (n-1) - (long long)cnt.size();
        return arr;
    }
};

