class Solution {
    public long[] countBlackBlocks(int m, int n, int[][] coordinates) {
        Map<Long, Integer> cnt = new HashMap<>();
        for (int[] c : coordinates)
            for (int bx = c[0]-1; bx <= c[0]; bx++)
                for (int by = c[1]-1; by <= c[1]; by++)
                    if (bx >= 0 && bx < m-1 && by >= 0 && by < n-1)
                        cnt.merge((long) bx * n + by, 1, Integer::sum);
        long[] arr = new long[5];
        for (int v : cnt.values()) arr[v]++;
        arr[0] = (long)(m-1) * (n-1) - cnt.size();
        return arr;
    }
}

